window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-338d0af6e8c898d8"]={"versions": [{"id": "FIG-338d0af6e8c898d8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Schichten- und Dokumentenhierarchie-Diagramm zur AUTOSAR-Spezifikationsarchitektur gemäß AUTOSAR_TPS_StandardizationTemplate. Das Modell strukturiert die Anforderungs- und Spezifikationsartefakte vertikal in fünf diskrete Spezifikationsebenen (Level 1 bis Level 5) und veranschaulicht deren Verfeinerungs- und Implementierungsbeziehungen („details“, „implements“) von allgemeinen Projektzielen bis zu konkreten Spezifikationen und Modellen. Am linken Rand kennzeichnen vertikale Orientierungsbalken die Ebenen 1 bis 3 als „Technological Conception / Technical Scope and Approach“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert Spezifikationsartefakte in Blöcke über fünf Ebenen:</p>\n<ul class=\"fig-list\">\n<li>Level 1: „AUTOSAR Project Objectives“</li>\n<li>Level 2: „AUTOSAR Main Requirements“</li>\n<li>Level 3: Drei domänenspezifische Feature-Dokumente: „AUTOSAR BSW & RTE Features“, „AUTOSAR Methodology and Template Features“ sowie „AUTOSAR Application Interfaces Features“.</li>\n<li>Level 4: Anforderungsdokumente (SRS / RS): „AUTOSAR SRS General“, „AUTOSAR SRS SPAL General“, „AUTOSAR SRSs BSW“, „AUTOSAR RSs M&T“ und „AUTOSAR RSs Application Interfaces“.</li>\n<li>Level 5: Spezifikations-, Modell- und Template-Artefakte: „AUTOSAR SWS, EXP“, „AUTOSAR TPS, TR, MMOD, MOD“ sowie „AUTOSAR MOD, EXP, TR“.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Vertikale Kanten mit Pfeilspitzen nach oben repräsentieren Rückführungen bzw. Verfeinerungen („details“) von Level 4 zu Level 3 sowie Abbildungen von Level 3 auf Level 2 („AUTOSAR Main Requirements“) und von Level 2 auf Level 1 („AUTOSAR Project Objectives“).</li>\n<li>Kanten von Level 5 zu Level 4 tragen das Stereotyp „implements“.</li>\n<li>Innerhalb von Level 4 referenziert „AUTOSAR SRS SPAL General“ sowohl „AUTOSAR SRS General“ als auch „AUTOSAR SRSs BSW“.</li>\n<li>„AUTOSAR SWS, EXP“ implementiert („implements“) sowohl „AUTOSAR SRS General“ als auch „AUTOSAR SRSs BSW“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Metamodell ohne Laufzeitverhalten. Dargestellt ist eine statische Traceability- und Verfeinerungskaskade:</p>\n<ol class=\"fig-list\">\n<li>Level 1 definiert übergeordnete Projektziele.</li>\n<li>Level 2 leitet daraus zentrale Hauptanforderungen (Main Requirements) ab.</li>\n<li>Level 3 strukturiert diese in Feature-Bündel der Domänen BSW/RTE, Methodik/Templates und Applikationsschnittstellen.</li>\n<li>Level 4 detailliert („details“) die Features in funktionale und generische Anforderungsspezifikationen (SRS/RS).</li>\n<li>Level 5 implementiert („implements“) die Anforderungen aus Level 4 in Form konkreter Software-Spezifikationen (SWS), Templates (TPS), Modelle (MOD/MMOD) und technischer Berichte bzw. Erläuterungen (TR/EXP).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassifikation bestimmt verbindlich die Dokumentstruktur und Nachverfolgbarkeit (Traceability) im AUTOSAR-Standardisierungsprozess. Entwickler und Spezifikationsautoren müssen nachweisen, dass SWS-, TPS- und MOD-Artefakte (Level 5) die übergeordneten SRS- und RS-Dokumente (Level 4) vollständig abdecken und implementieren. Die Zuordnung definiert die zulässige Richtung von Anforderungsreferenzen und Konformitätsnachweisen.</p>"}, {"id": "FIG-a9063126143579f0", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Schichten- und Dokumentenhierarchie-Diagramm zur AUTOSAR-Spezifikationsarchitektur gemäß AUTOSAR_TPS_StandardizationTemplate. Das Modell strukturiert die Anforderungs- und Spezifikationsartefakte vertikal in fünf diskrete Spezifikationsebenen (Level 1 bis Level 5) und veranschaulicht deren Verfeinerungs- und Implementierungsbeziehungen („details“, „implements“) von allgemeinen Projektzielen bis zu konkreten Spezifikationen und Modellen. Am linken Rand kennzeichnen vertikale Orientierungsbalken die Ebenen 1 bis 3 als „Technological Conception / Technical Scope and Approach“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert Spezifikationsartefakte in Blöcke über fünf Ebenen:</p>\n<ul class=\"fig-list\">\n<li>Level 1: „AUTOSAR Project Objectives“</li>\n<li>Level 2: „AUTOSAR Main Requirements“</li>\n<li>Level 3: Zentraler, einheitlicher Block „AUTOSAR Features“.</li>\n<li>Level 4: Anforderungsdokumente (SRS / RS): „AUTOSAR SRS General“, „AUTOSAR SRS SPAL General“, „AUTOSAR SRSs BSW“, „AUTOSAR RSs M&T“ und „AUTOSARRSs Application Interfaces“.</li>\n<li>Level 5: Spezifikations-, Modell- und Template-Artefakte: „AUTOSAR SWS, EXP“, „AUTOSAR TPS, TR, MMOD, MOD“ sowie „AUTOSAR MOD, EXP, TR“.</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Level 5 zu Level 4: Kanten mit dem Stereotyp „implements“ führen von „AUTOSAR SWS, EXP“ zu „AUTOSAR SRS SPAL General“ und „AUTOSAR SRSs BSW“, von „AUTOSAR TPS, TR, MMOD, MOD“ zu „AUTOSAR RSs M&T“ sowie von „AUTOSAR MOD, EXP, TR“ zu „AUTOSARRSs Application Interfaces“.</li>\n<li>Innerhalb von Level 4: „AUTOSAR SRS SPAL General“ referenziert „AUTOSAR SRS General“.</li>\n<li>Level 4 zu Level 3: Vier Kanten mit dem Stereotyp „details“ führen von „AUTOSAR SRS General“, „AUTOSAR SRSs BSW“, „AUTOSAR RSs M&T“ und „AUTOSARRSs Application Interfaces“ auf den gemeinsamen Block „AUTOSAR Features“.</li>\n<li>Level 3 zu Level 2: Ein zentraler Pfeil verbindet „AUTOSAR Features“ mit „AUTOSAR Main Requirements“.</li>\n<li>Level 2 zu Level 1: Ein Pfeil verbindet „AUTOSAR Main Requirements“ mit „AUTOSAR Project Objectives“.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Architektur- und Metamodell ohne Laufzeitverhalten. Dargestellt ist eine konsolidierte Traceability- und Verfeinerungskaskade:</p>\n<ol class=\"fig-list\">\n<li>Level 1 definiert übergeordnete Projektziele („AUTOSAR Project Objectives“).</li>\n<li>Level 2 bündelt die zentralen Anforderungen („AUTOSAR Main Requirements“).</li>\n<li>Level 3 konsolidiert alle Spezifikationsmerkmale in einem zentralen Merkmalspool („AUTOSAR Features“).</li>\n<li>Level 4 detailliert („details“) die Merkmale über domänenspezifische Anforderungsspezifikationen (SRS/RS).</li>\n<li>Level 5 setzt („implements“) die Anforderungen der Ebene 4 in Ausarbeitungsspezifikationen (SWS), Templates (TPS), Metamodellen (MOD/MMOD) und begleitenden Dokumenten (TR/EXP) um.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassifikation bestimmt verbindlich die Dokumentstruktur und Nachverfolgbarkeit (Traceability) im AUTOSAR-Standardisierungsprozess. Entwickler und Spezifikationsautoren müssen nachweisen, dass SWS-, TPS- und MOD-Artefakte (Level 5) die übergeordneten SRS- und RS-Dokumente (Level 4) vollständig abdecken und implementieren. Die Zuordnung definiert die zulässige Richtung von Anforderungsreferenzen und Konformitätsnachweisen.</p>"}, {"id": "FIG-b93a4bda0a1fb3d3", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Schichten- und Traceability-Diagramm zur AUTOSAR-Spezifikations- und Testarchitektur gemäß AUTOSAR_TPS_StandardizationTemplate. Das Diagramm ist durch eine vertikale gestrichelte Linie in zwei Hauptbereiche unterteilt: die Software-Spezifikation („Software Specification“, links) und die Akzeptanztest-Spezifikation („Acceptence Tests Specification“, rechts). Beide Stränge erstrecken sich über die fünf Spezifikationsebenen (Level 1 bis Level 5) und sind über funktionale Traceability- und Testbeziehungen („details“, „implements“, „tests“) miteinander verknüpft. Links kennzeichnen vertikale Balken die Ebenen 1 bis 3 als „Technological Conception / Technical Scope and Approach“.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert Spezifikations- und Testartefakte über zwei parallele Stränge auf fünf Ebenen:</p>\n<ol class=\"fig-list\">\n<li>Software Specification (linker Strang):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Level 1: „AUTOSAR Project Objectives“</li>\n<li>Level 2: „AUTOSAR Main Requirements“</li>\n<li>Level 3: Breiter horizontaler Block „AUTOSAR Features“</li>\n<li>Level 4: „AUTOSAR SRS General“, „AUTOSAR SRS SPAL General“, „AUTOSAR SRSs BSW“, „AUTOSAR RSs M&T“, „AUTOSAR RSs Application Interfaces“</li>\n<li>Level 5: „AUTOSAR SWS, EXP“, „AUTOSAR TPS,TR,MMOD,MOD“, „AUTOSAR MOD,EXP,TR“</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Acceptence Tests Specification (rechter Teststrang):</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Level 2: „AUTOSAR ATR Main“ (Acceptance Test Requirements Main)</li>\n<li>Level 3: „AUTOSAR ATR Features“</li>\n<li>Level 4: „AUTOSAR ATR“</li>\n<li>Level 5: „AUTOSAR ATS“ (Acceptance Test Specifications)</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li>Innerhalb des Teststrangs: „AUTOSAR ATS“ implementiert („implements“) „AUTOSAR ATR“; „AUTOSAR ATR“ detailliert („details“) „AUTOSAR ATR Features“; „AUTOSAR ATR Features“ führt nach oben auf „AUTOSAR ATR Main“; „AUTOSAR ATR Main“ verweist ebenenübergreifend direkt auf „AUTOSAR Project Objectives“ (Level 1).</li>\n<li>Querverbindungen Spezifikation / Test:</li>\n<li>„AUTOSAR ATR“ (Level 4 Test) testet („tests“) „AUTOSAR SRSs BSW“ und „AUTOSAR RSs M&T“ (Level 4 Software).</li>\n<li>„AUTOSAR ATS“ (Level 5 Test) testet („tests“) „AUTOSAR MOD,EXP,TR“ sowie „AUTOSAR TPS,TR,MMOD,MOD“ (Level 5 Software).</li>\n<li>Innerhalb der Software Specification:</li>\n<li>Kanten mit „implements“ von Level 5 auf Level 4.</li>\n<li>Horizontale Referenz auf Level 5 von „AUTOSAR TPS,TR,MMOD,MOD“ auf „AUTOSAR SWS, EXP“.</li>\n<li>Direkte Kanten von Level 5 („AUTOSAR SWS, EXP“) auf Level 3 („AUTOSAR Features“).</li>\n<li>Kanten mit „details“ von Level 4 auf „AUTOSAR Features“ (Level 3).</li>\n<li>Kante von „AUTOSAR RSs M&T“ (Level 4) direkt auf „AUTOSAR Main Requirements“ (Level 2).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Beziehungs- und Verifikationsmodell. Die Verfeinerungskaskade verzweigt sich in zwei interagierende Zyklen:</p>\n<ol class=\"fig-list\">\n<li>Anforderungs- und Spezifikationspfad (links): Projektziele (L1) -> Hauptanforderungen (L2) -> Features (L3) -> SRS/RS (L4) -> Implementierungsspezifikationen SWS/TPS/MOD (L5).</li>\n<li>Test- und Verifikationspfad (rechts): Aus den Projektzielen (L1) leiten sich übergeordnete Testanforderungen (ATR Main, L2) und Test-Features (L3) ab, die in ATR (L4) detailliert werden.</li>\n<li>Verifikationsfluss („tests“): ATR auf Level 4 verifiziert die SRS/RS-Anforderungen auf Level 4; ATS auf Level 5 verifiziert die Spezifikations- und Modell-Artefakte (TPS/MOD) auf Level 5.</li>\n<li>Rückkopplung: Spezifikationsartefakte auf Level 5 („AUTOSAR SWS, EXP“) können direkt an Features auf Level 3 rückgekoppelt sein.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Einführung des separaten Akzeptanztest-Zweigs („Acceptence Tests Specification“) etabliert normative Testanforderungen (ATR) und Testspezifikationen (ATS) als formale Gegenstücke zu den Software-Spezifikationen. Entwickler und Testingenieure müssen die bidirektionale Nachverfolgbarkeit sicherstellen: Nicht nur müssen SWS und Metamodelle die SRS/RS-Vorgaben erfüllen („implements“), sondern Akzeptanztests (ATS/ATR) müssen explizit gegen die korrespondierenden Software-Anforderungen und Spezifikationsdokumente trassiert sein („tests“).</p>"}], "trans": [{"from": "FIG-338d0af6e8c898d8", "to": "FIG-a9063126143579f0", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Level 3: Die drei separaten Blöcke „AUTOSAR BSW & RTE Features“, „AUTOSAR Methodology and Template Features“ und „AUTOSAR Application Interfaces Features“ sind zu einem einzigen zentralen Block „AUTOSAR Features“ zusammengefasst.</li>\n<li>Beziehungen Level 4 zu Level 3: Die Pfeile mit Stereotyp „details“ von „AUTOSAR SRS General“, „AUTOSAR SRSs BSW“, „AUTOSAR RSs M&T“ sowie „AUTOSAR RSs Application Interfaces“ führen nun alle direkt auf den zusammengefassten Block „AUTOSAR Features“.</li>\n<li>Level 2 zu Level 3: Der Block „AUTOSAR Features“ verweist über einen einzelnen Pfeil nach oben auf „AUTOSAR Main Requirements“.</li>\n<li>Beschriftung: Im Block auf Level 4 wurde „AUTOSAR RSs Application Interfaces“ typografisch zu „AUTOSARRSs Application Interfaces“ zusammengezogen.</li>\n</ul>"}, {"from": "FIG-a9063126143579f0", "to": "FIG-b93a4bda0a1fb3d3", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Diagrammstruktur: Zweiteilung durch eine vertikale gestrichelte Trennlinie in „Software Specification“ (links) und den neuen Strang „Acceptence Tests Specification“ (rechts).</li>\n<li>Neue Entitäten im Teststrang:</li>\n<li>Level 2: „AUTOSAR ATR Main“</li>\n<li>Level 3: „AUTOSAR ATR Features“</li>\n<li>Level 4: „AUTOSAR ATR“</li>\n<li>Level 5: „AUTOSAR ATS“</li>\n<li>Neue Beziehungen innerhalb des Teststrangs:</li>\n<li>Level 5 zu Level 4: Pfeil mit Stereotyp „implements“ von „AUTOSAR ATS“ zu „AUTOSAR ATR“.</li>\n<li>Level 4 zu Level 3: Pfeil mit Stereotyp „details“ von „AUTOSAR ATR“ zu „AUTOSAR ATR Features“.</li>\n<li>Level 3 zu Level 2: Pfeil von „AUTOSAR ATR Features“ zu „AUTOSAR ATR Main“.</li>\n<li>Neue querschnittliche Beziehungen zwischen Spezifikation und Test:</li>\n<li>Level 2 zu Level 1: Pfeil von „AUTOSAR ATR Main“ zu „AUTOSAR Project Objectives“.</li>\n<li>Level 4 (Test zu Software): Pfeile mit Stereotyp „tests“ von „AUTOSAR ATR“ zu „AUTOSAR SRSs BSW“ und zu „AUTOSAR RSs M&T“.</li>\n<li>Level 5 (Test zu Software): Pfeile mit Stereotyp „tests“ von „AUTOSAR ATS“ zu „AUTOSAR MOD, EXP, TR“ sowie zu „AUTOSAR TPS, TR, MMOD, MOD“.</li>\n<li>Neue Beziehungen innerhalb der Software-Spezifikation (Level 5):</li>\n<li>Horizontaler Pfeil von „AUTOSAR TPS, TR, MMOD, MOD“ zu „AUTOSAR SWS, EXP“.</li>\n<li>Geänderte Pfeilführungen:</li>\n<li>Von „AUTOSAR SWS, EXP“ führt nun ein Pfeil direkt auf „AUTOSAR Features“ (Level 3).</li>\n<li>Von „AUTOSAR RSs M&T“ (Level 4) führt ein Pfeil direkt auf „AUTOSAR Project Objectives“ bzw. „AUTOSAR Main Requirements“.</li>\n<li>„AUTOSAR Features“ ist auf Level 3 horizontal über die gesamte Breite der Software-Spezifikation verbreitert.</li>\n</ul>"}]};
